ALTER TABLE executions ADD COLUMN environment_preservation_required INTEGER NOT NULL DEFAULT 0 CHECK(environment_preservation_required IN (0,1)); CREATE TRIGGER executions_environment_preservation_write_once BEFORE UPDATE OF environment_preservation_required ON executions WHEN NOT (NEW.environment_preservation_required=OLD.environment_preservation_required OR (OLD.state='dispatching' AND NEW.state='running' AND OLD.environment_preservation_required=0 AND NEW.environment_preservation_required=1)) BEGIN SELECT RAISE(ABORT,'sqlite.execution_environment_preservation_write_once'); END;
